1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
7	
8	/**
9	 * Consolidated duplicate detection for {@code POST /api/owners}: rejects a create with 409 via
10	 * {@link DuplicateIdentityException} only when the new owner's WHOLE {@code identityKey} (see
11	 * {@link IdentityKey}) — {@code normalizedTelephone|email|householdId} — equals an existing owner's,
12	 * i.e. the same telephone, email and household. Members of the same household with a different
13	 * telephone (or email) have different keys, so several owners may legitimately share one household;
14	 * this is what lets a household accumulate members for the membership-level cap (see
15	 * {@link CapMembershipLevel}). Only a truly identical record is a conflict.
16	 *
17	 * <p>Runs after {@link AssignHousehold}, so the new owner's householdId is finalized before it is
18	 * compared, and before {@link SaveOwner}. Soft-deleted owners no longer block a create.
19	 */
20	public class EnsureUniqueIdentity {
21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
23	            throws DuplicateIdentityException {
24	        String identityKey = IdentityKey.of(owner);
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
27	                continue; // the owner being created is not yet its own duplicate
28	            }
29	            if (Boolean.TRUE.equals(existing.getDeleted())) {
30	                continue; // a soft-deleted owner no longer blocks a create
31	            }
32	            if (IdentityKey.of(existing).equals(identityKey)) {
33	                throw new DuplicateIdentityException(identityKey);
34	            }
35	        }
36	    }
37	}
