9	/**
10	 * Rejects an owner request whose {@code email} domain is on the disposable-domain blocklist
11	 * (mailinator.com, tempmail.com, guerrillamail.com) with a 400 via
12	 * {@link DisposableEmailDomainException}. Email is optional: a null or blank value is left
13	 * untouched. Runs after {@link NormalizeOwnerEmail}, which validates syntax and lower-cases the
14	 * address, so the domain compares case-insensitively against the lower-case blocklist.
15	 */
16	public class RejectDisposableEmailDomain {
17	
18	    private static final Set<String> BLOCKED_DOMAINS = Set.of(
19	            "mailinator.com", "tempmail.com", "guerrillamail.com");
20	
21	    public void service(@Val OwnerFieldsDto request) throws DisposableEmailDomainException {
22	        String email = request.getEmail();
23	        if (email == null || email.isBlank()) {
24	            return; // email is optional
25	        }
26	        int at = email.lastIndexOf('@');
27	        if (at < 0) {
28	            return; // syntax already validated upstream; nothing to block
29	        }
30	        String domain = email.substring(at + 1).trim().toLowerCase();
31	        if (BLOCKED_DOMAINS.contains(domain)) {
32	            throw new DisposableEmailDomainException(email);
33	        }
34	    }
35	}
