3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	
6	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
7	
8	/**
9	 * Converts a supplied telephone into E.164 form. Spaces, dashes and brackets are stripped; a leading
10	 * '+' with its country code is kept when present, otherwise country code '+61' is assumed and a single
11	 * leading '0' is dropped from the national digits. The result must carry 8 to 15 digits after the '+',
12	 * otherwise it cannot form a valid E.164 number and an {@link InvalidTelephoneException} (400) is thrown.
13	 *
14	 * <p>For a recognized country code the national number (the digits after the country code) must also be
15	 * exactly the length that country requires — '+61' (Australia) requires 9 national digits and '+1'
16	 * (NANP) requires 10. A wrong national-number length for the country is likewise rejected with a 400.
17	 */
18	public final class E164Telephone {
19	
20	    /** Country code (digits after the '+', without it) -> required national-number length. Ordered
21	     *  longest-first so the most specific prefix wins when resolving the country code. */
22	    private static final Map<String, Integer> NATIONAL_LENGTH = new LinkedHashMap<>();
23	
24	    static {
25	        NATIONAL_LENGTH.put("61", 9); // Australia
26	        NATIONAL_LENGTH.put("1", 10); // NANP
27	    }
28	
29	    private E164Telephone() {
30	    }
31	
32	    static String normalize(String telephone) throws InvalidTelephoneException {
33	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\[\\]-]", "");
34	        boolean hasPlus = cleaned.startsWith("+");
35	        String rest = hasPlus ? cleaned.substring(1) : cleaned;
36	        if (rest.isEmpty() || !rest.chars().allMatch(Character::isDigit)) {
37	            throw new InvalidTelephoneException(telephone);
38	        }
39	        String digits;
40	        if (hasPlus) {
41	            digits = rest;
42	        }
43	        else {
44	            String national = rest.startsWith("0") ? rest.substring(1) : rest;
45	            digits = "61" + national;
46	        }
47	        if (digits.length() < 8 || digits.length() > 15) {
48	            throw new InvalidTelephoneException(telephone);
49	        }
50	        for (Map.Entry<String, Integer> country : NATIONAL_LENGTH.entrySet()) {
51	            String code = country.getKey();
52	            if (digits.startsWith(code)) {
53	                if (digits.length() - code.length() != country.getValue()) {
54	                    throw new InvalidTelephoneException(telephone);
55	                }
56	                break;
57	            }
58	        }
59	        return "+" + digits;
60	    }
61	
62	    /**
63	     * Formats a stored E.164 telephone for humans: the '+' and country code, a space, then the
64	     * national digits grouped in threes (e.g. {@code +61412345678} becomes {@code +61 412 345 678}).
65	     * A recognized country code is split off; otherwise the leading digits up to the first three are
66	     * treated as the country code. Anything that is not a '+' followed by digits is returned verbatim.
67	     */
68	    public static String display(String e164) {
69	        if (e164 == null || !e164.startsWith("+")) {
70	            return e164;
71	        }
72	        String digits = e164.substring(1);
73	        if (digits.isEmpty() || !digits.chars().allMatch(Character::isDigit)) {
74	            return e164;
75	        }
76	        String code = null;
77	        for (String candidate : NATIONAL_LENGTH.keySet()) {
78	            if (digits.startsWith(candidate) && digits.length() > candidate.length()) {
79	                code = candidate;
80	                break;
81	            }
82	        }
83	        if (code == null) {
84	            code = digits.substring(0, Math.min(3, digits.length()));
85	        }
86	        String national = digits.substring(code.length());
87	        StringBuilder sb = new StringBuilder("+").append(code);
88	        for (int i = 0; i < national.length(); i += 3) {
89	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
90	        }
91	        return sb.toString();
92	    }
93	}
