7	/**
8	 * Step of {@code POST /api/owners} that records the size of the owner's household after this create:
9	 * the number of owners sharing the same {@code householdId}, counting the owner being created.
10	 *
11	 * <p>Runs after {@link AssignHousehold}, which assigns the deterministic {@code householdId} that
12	 * every member of a household shares, and before {@link SaveOwner}. Because the new owner is not yet
13	 * persisted, it is counted explicitly (the {@code + 1}); existing members are counted from the
14	 * repository. When the owner has no {@code householdId} (it is not part of a shared household) the
15	 * size is 1.
16	 */
17	public class AssignHouseholdSize {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        String householdId = owner.getHouseholdId();
21	        if (householdId == null) {
22	            owner.setHouseholdSize(1);
23	            return;
24	        }
25	        int count = 1;
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (householdId.equals(existing.getHouseholdId())) {
28	                count++;
29	            }
30	        }
31	        owner.setHouseholdSize(count);
32	    }
33	}
