	}

	protected int extractId(ResultActions ra) throws Exception {
		String body = ra.andReturn().getResponse().getContentAsString();
		if (body != null && !body.isBlank()) {
			JsonNode n = om.readTree(body);
			if (n.hasNonNull("id")) {
				return n.get("id").asInt();
